insert into seed_menus values
(0,'Simple Veg Week','Everyday North + South Indian veg food. No fancy ingredients, mostly 30 minutes or less.','week',7,'veg',array['everyday','quick']::text[]),
(1,'High-Protein Veg Week','Dal, paneer, chana and sprouts every day. Roughly 25–30 g protein per meal for one adult.','week',7,'veg',array['high-protein','fitness']::text[]),
(2,'South Indian Week','Idli, dosa, pongal, sambar and curd rice. Batter once, eat all week.','week',7,'veg',array['south-indian']::text[]),
(3,'Student Budget Week','Cheap staples, one-pot dinners and lots of dal. Built for a small kitchen and a tight budget.','week',7,'veg',array['budget','one-pot']::text[]),
(4,'Eggetarian Week','Veg meals with eggs for breakfast and a couple of dinners.','week',7,'egg',array['high-protein']::text[]),
(5,'Lean Non-Veg Week','Chicken, fish and eggs with simple sides. High protein, light dinners.','week',7,'nonveg',array['high-protein','fitness']::text[]),
(6,'Jain Week','No onion, no garlic, no root vegetables.','week',7,'jain',array['no-onion-garlic']::text[]),
(7,'Light Reset Day','A gentle day after a heavy weekend: oats, curd rice and khichdi.','day',1,'veg',array['light']::text[]),
(8,'Sunday Feast','Aloo paratha brunch, veg biryani lunch and dal makhani dinner.','day',1,'veg',array['weekend']::text[]),
(9,'Balanced Veg Month','Four different veg weeks back to back: everyday, South Indian, high-protein and budget.','month',28,'veg',array['everyday','variety']::text[]);
